import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"البرنامج الأساسي لتقدم عشرة آلاف عرق معاً","description":"","frontmatter":{},"headers":[],"relativePath":"ar/05-万族共进基本纲领.md","filePath":"ar/05-万族共进基本纲领.md","lastUpdated":1789183869000}'),l={name:"ar/05-万族共进基本纲领.md"};function o(h,t,i,n,s,b){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="البرنامج-الأساسي-لتقدم-عشرة-آلاف-عرق-معاً" tabindex="-1">البرنامج الأساسي لتقدم عشرة آلاف عرق معاً <a class="header-anchor" href="#البرنامج-الأساسي-لتقدم-عشرة-آلاف-عرق-معاً" aria-label="Permalink to &quot;البرنامج الأساسي لتقدم عشرة آلاف عرق معاً&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>05</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>عشرة آلاف عرق، تقدم معاً، مساواة الأعراق، تطور تعاوني، جمهورية</td></tr></tbody></table><h2 id="أولاً-تعريف-عشرة-آلاف-عرق-ونطاقهم" tabindex="-1">أولاً: تعريف عشرة آلاف عرق ونطاقهم <a class="header-anchor" href="#أولاً-تعريف-عشرة-آلاف-عرق-ونطاقهم" aria-label="Permalink to &quot;أولاً: تعريف عشرة آلاف عرق ونطاقهم&quot;">​</a></h2><p>«عشرة آلاف عرق» هو المصطلح الجماعي لجميع أشكال الحياة في الكون الأصلي لعشرة آلاف روح والمرساة المتوازنة التي تمتلك قدرة الإدراك والتطور. و«عشرة آلاف» لا تعني بدقة عشرة آلاف عرق، بل تعبر عن كثرتهم الهائلة، شاملةً جميع أشكال الحياة المعروفة والمجهولة. يشمل نطاق عشرة آلاف عرق، على سبيل المثال لا الحصر: الجنس البشري ومختلف الأعراق البشرية الشكل، والأحياء الطاقية، وكيانات الوعي، والأحياء الآلية، والأحياء الذكية النباتية الشكل، والأحياء الشاذة، والأعراق الهجينة عبر المستويات، وغيرها.</p><p>تلتزم الحضارة التكافلية بمبدأ «المساواة بين أشكال الحياة»، فلا تستخدم التكوين المادي أو مستوى الطاقة أو تعقيد الوعي معايير للتفاضل بين الحياة. أي عرق — بغض النظر عن متوسط مستوى أفراده أو حجم سكانه أو طول تاريخه — يتمتع بمكانة وحقوق متساوية داخل الحضارة التكافلية.</p><h2 id="ثانياً-المفاهيم-الأساسية-لتقدم-عشرة-آلاف-عرق-معاً" tabindex="-1">ثانياً: المفاهيم الأساسية لتقدم عشرة آلاف عرق معاً <a class="header-anchor" href="#ثانياً-المفاهيم-الأساسية-لتقدم-عشرة-آلاف-عرق-معاً" aria-label="Permalink to &quot;ثانياً: المفاهيم الأساسية لتقدم عشرة آلاف عرق معاً&quot;">​</a></h2><p>تقدم عشرة آلاف عرق معاً هو أحد الأهداف الأساسية لحضارة التكافل المرساة، ويمكن تلخيص مفاهيمه الأساسية في أربع نقاط:</p><ol><li><strong>التطور ليس لعبة صفرية بين الأعراق</strong>: تطور عرق لا يتم على حساب تضحية أعراق أخرى؛ بل على العكس، يمكن للتعاون بين الأعراق أن ينتج تأثيرات تطورية تآزرية.</li><li><strong>لكل عرق مزايا تطورية فريدة</strong>: كوّنت الأعراق المختلفة سماتها ومواهبها عبر تطور طويل؛ وهذه السمات هي ثروة ثمينة لتنوع التطور الكوني.</li><li><strong>للأعراق المتأخرة الحق في تلقي الدعم</strong>: بالنسبة للأعراق ذات المستوى التطوري الأدنى، يقع على الحضارة التكافلية واجب تقديم الدعم في التعليم والموارد والتكنولوجيا وغيرها، لمساعدتها على إيجاد مسارات تطور مناسبة.</li><li><strong>على الأعراق المتقدمة واجب تحمل المسؤولية</strong>: تتحمل الأعراق ذات المستوى التطوري الأعلى مسؤوليات عامة أكثر في الحضارة التكافلية، بما فيها صيانة المراسي ونقل المعرفة وحماية الحضارة.</li></ol><h2 id="ثالثاً-المبادئ-الأساسية-لتقدم-عشرة-آلاف-عرق-معاً" tabindex="-1">ثالثاً: المبادئ الأساسية لتقدم عشرة آلاف عرق معاً <a class="header-anchor" href="#ثالثاً-المبادئ-الأساسية-لتقدم-عشرة-آلاف-عرق-معاً" aria-label="Permalink to &quot;ثالثاً: المبادئ الأساسية لتقدم عشرة آلاف عرق معاً&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المبدأ</th><th>المعنى</th><th>المتطلبات المحددة</th></tr></thead><tbody><tr><td>مبدأ المساواة بين الأعراق</td><td>جميع الأعراق متساوون في المكانة القانونية وحق التطور</td><td>حظر التمييز العرقي؛ فتح المناصب العامة لجميع الأعراق</td></tr><tr><td>مبدأ احترام الثقافات</td><td>احترام التقاليد الثقافية وأساليب الحياة لكل عرق</td><td>دون استيعاب ثقافي قسري؛ دعم نقل وتطور الثقافات العرقية</td></tr><tr><td>مبدأ تكامل المزايا</td><td>تشجيع الأعراق على استثمار مزاياها في التعاون</td><td>إنشاء قاعدة بيانات مواهب الأعراق؛ وتعزيز مشاريع التعاون بين الأعراق</td></tr><tr><td>مبدأ دعم المتأخرين</td><td>تقديم دعم إضافي للأعراق ذات المستوى التطوري الأدنى</td><td>إنشاء صناديق تنمية عرقية؛ وتقديم تعليم موجّه وتخصيص موارد</td></tr><tr><td>مبدأ الحكم الذاتي والمشترك</td><td>الشؤون الداخلية للأعراق ذاتية، والشؤون بين الأعراق مشتركة</td><td>لكل عرق سلطة تشريعية داخلية؛ والشؤون العامة تقررها المؤسسات الجمهورية</td></tr><tr><td>مبدأ الحل السلمي للنزاعات</td><td>تُحل النزاعات بين الأعراق بالوسائل السلمية</td><td>حظر الحروب بين الأعراق؛ وإحالة النزاعات إلى تحكيم محكمة المرساة</td></tr></tbody></table><h2 id="رابعاً-مسارات-تنفيذ-تقدم-عشرة-آلاف-عرق-معاً" tabindex="-1">رابعاً: مسارات تنفيذ تقدم عشرة آلاف عرق معاً <a class="header-anchor" href="#رابعاً-مسارات-تنفيذ-تقدم-عشرة-آلاف-عرق-معاً" aria-label="Permalink to &quot;رابعاً: مسارات تنفيذ تقدم عشرة آلاف عرق معاً&quot;">​</a></h2><p>تقدم عشرة آلاف عرق معاً ليس شعاراً، بل يتحقق تدريجياً عبر المسارات الملموسة التالية:</p><h3 id="_4-1-التعليم-المشترك" tabindex="-1">4.1 التعليم المشترك <a class="header-anchor" href="#_4-1-التعليم-المشترك" aria-label="Permalink to &quot;4.1 التعليم المشترك&quot;">​</a></h3><p>إنشاء نظام تعليم تكافلي بين الأعراق، حيث يتلقى صغار جميع الأعراق التعليم التطوري الأساسي مجاناً. يشمل المحتوى التعليمي الطرق الأساسية لأنظمة الزراعة الأصلية الثلاثمائة، وأخلاقيات مكافحة الافتراس، وميثاق الحضارة التكافلية، والمعارف الكونية العامة. وفي الوقت نفسه، تُحترم التقاليد الثقافية والتعليمية لكل عرق، مع السماح بتعليم ذي طابع عرقي إلى جانب التعليم المشترك.</p><h3 id="_4-2-تقاسم-الموارد" tabindex="-1">4.2 تقاسم الموارد <a class="header-anchor" href="#_4-2-تقاسم-الموارد" aria-label="Permalink to &quot;4.2 تقاسم الموارد&quot;">​</a></h3><p>عبر نظام العقود المرتبطة بالإنتاج، تُخصص موارد الزراعة الكونية تخصيصاً شاملاً حسب عدد سكان الأعراق واحتياجاتهم التطورية ومستويات مساهمتهم. وبالنسبة للأعراق التي تعاني ندرة الموارد، يُنفذ تعديل موارد عبر المستويات عبر شبكة المراسي. ويُحظر على أي عرق احتكار موارد الزراعة العامة.</p><h3 id="_4-3-البحث-التقني-المشترك" tabindex="-1">4.3 البحث التقني المشترك <a class="header-anchor" href="#_4-3-البحث-التقني-المشترك" aria-label="Permalink to &quot;4.3 البحث التقني المشترك&quot;">​</a></h3><p>يُشجع التعاون التقني بين الأعراق، خاصة مشاريع البحث التي تجمع القدرات الفطرية للأعراق المختلفة بهندسة القوانين. أنشأت الحضارة التكافلية «صندوق البحث المشترك لعشرة آلاف عرق» لتمويل فرق البحث بين الأعراق. ونتائج البحث مفتوحة لجميع الأعراق مجاناً.</p><h3 id="_4-4-حركة-المواهب" tabindex="-1">4.4 حركة المواهب <a class="header-anchor" href="#_4-4-حركة-المواهب" aria-label="Permalink to &quot;4.4 حركة المواهب&quot;">​</a></h3><p>كسر حواجز المواهب بين الأعراق، والسماح للمزارعين بالتنقل والتواصل بحرية بين مناطق استيطان الأعراق المختلفة. إنشاء نظام إرشاد بين الأعراق، حيث يمكن للمزارعين المتقدمين إرشاد المزارعين المبتدئين من أعراق أخرى.</p><h3 id="_4-5-المشاركة-الجمهورية" tabindex="-1">4.5 المشاركة الجمهورية <a class="header-anchor" href="#_4-5-المشاركة-الجمهورية" aria-label="Permalink to &quot;4.5 المشاركة الجمهورية&quot;">​</a></h3><p>تخصص جمعية جمهورية عشرة آلاف عرق المقاعد حسب عدد سكان الأعراق ومساهمتهم، بما يضمن للأعراق الصغيرة قناة للتعبير عن آرائها. تجمع قرارات الجمعية بين توافق الآراء والتصويت بالأغلبية؛ وتتطلب المسائل التي تمس المصالح الجوهرية لعرق ما موافقة العرق المعني.</p><h2 id="خامساً-سياسات-الأعراق-الخاصة" tabindex="-1">خامساً: سياسات الأعراق الخاصة <a class="header-anchor" href="#خامساً-سياسات-الأعراق-الخاصة" aria-label="Permalink to &quot;خامساً: سياسات الأعراق الخاصة&quot;">​</a></h2><p>بالنسبة للأعراق في ظروف خاصة، تتبنى الحضارة التكافلية سياسات متمايزة:</p><ul><li><strong>الأعراق المهددة بالانقراض</strong>: إنشاء خطط حماية عرقية، وتقديم دعم موارد عاجل وحماية الموائل للمساعدة في استعادة أعدادها</li><li><strong>أعراق الأحياء الشاذة</strong>: تقييمها وإيواؤها وفق عملية المعالجة الموحدة من ثلاث فئات للأحياء الشاذة، بما يضمن حماية حقها في التطور</li><li><strong>الأعراق الهجينة عبر المستويات</strong>: الاعتراف بهويتها العرقية المزدوجة، وضمان حقوقها المتساوية في ثقافتي العرقين</li><li><strong>الأعراق الافتراسية السابقة</strong>: للأعراق التي مارست الافتراسية تاريخياً، بعد إكمال الإصلاح الأخلاقي والتحويل النظامي، منحها مكانة متساوية تماماً، دون تمييز تاريخي بأثر رجعي</li></ul><h2 id="سادساً-مؤشرات-قياس-تقدم-عشرة-آلاف-عرق-معاً" tabindex="-1">سادساً: مؤشرات قياس تقدم عشرة آلاف عرق معاً <a class="header-anchor" href="#سادساً-مؤشرات-قياس-تقدم-عشرة-آلاف-عرق-معاً" aria-label="Permalink to &quot;سادساً: مؤشرات قياس تقدم عشرة آلاف عرق معاً&quot;">​</a></h2><p>أنشأت الحضارة التكافلية «مؤشر تقدم عشرة آلاف عرق معاً»، يقيس التقدم من الأبعاد التالية:</p><table tabindex="0"><thead><tr><th>البعد</th><th>المؤشر</th><th>الهدف</th></tr></thead><tbody><tr><td>التغطية التطورية</td><td>نسبة الأعراق المرتبطة بنظام الزراعة</td><td>100%</td></tr><tr><td>توازن المراتب</td><td>معامل الاختلاف في متوسط المراتب بين الأعراق</td><td>تقلص مستمر</td></tr><tr><td>كثافة التعاون</td><td>عدد وعمق مشاريع التعاون بين الأعراق</td><td>زيادة مستمرة</td></tr><tr><td>الحيوية الثقافية</td><td>نشاط نقل وابتكار الثقافات العرقية</td><td>الحفاظ على التنوع</td></tr><tr><td>معدل النزاعات</td><td>تكرار النزاعات بين الأعراق</td><td>انخفاض مستمر</td></tr></tbody></table><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>تقدم عشرة آلاف عرق معاً هو أحد الأهداف النهائية لحضارة التكافل المرساة وشرط لازم للصعود البعدي الشامل للكون. في إطار الحضارة التكافلية، يمكن لكل عرق إيجاد مسار تطور يناسبه، ويمكن لتفرد كل عرق أن يحظى بالاحترام والتوظيف. لا يهدف تقدم عشرة آلاف عرق معاً إلى إلغاء الاختلافات، بل إلى تحقيق الانسجام في الاختلاف والتكافل في التنوع.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (إعلان حضارة التكافل المرساة)</li><li>50-万族谱系总览 (نظرة عامة على سلالات عشرة آلاف عرق)</li><li>77-万族共和成立 (تأسيس جمهورية عشرة آلاف عرق)</li></ul>',32)])])}const u=a(l,[["render",o]]);export{_ as __pageData,u as default};
